--
-- Table structure for table `product_variant`
--

DROP TABLE IF EXISTS `product_variant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_variant` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `sku` varchar(50) NOT NULL,
  `size` varchar(20) NOT NULL,
  `color` varchar(40) NOT NULL,
  `price` int NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_variant_sku_key` (`sku`),
  UNIQUE KEY `product_variant_product_id_size_color_key` (`product_id`,`size`,`color`),
  KEY `product_variant_product_id_idx` (`product_id`),
  KEY `product_variant_color_idx` (`color`),
  KEY `product_variant_product_id_price_idx` (`product_id`,`price`),
  CONSTRAINT `product_variant_product_id_fkey` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `product_variant_price_check` CHECK ((`price` > 0)),
  CONSTRAINT `product_variant_stock_check` CHECK ((`stock` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=547 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

